import os
import hashlib
import hmac
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, send_file
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

SECRET_KEY = os.environ.get('HMAC_KEY', secrets.token_hex(32)).encode()
BASE_DIR = '/srv/documents'
ALLOWED_EXTENSIONS = {'.pdf', '.txt', '.docx', '.xlsx', '.png', '.jpg'}

def generate_token(username, path):
    msg = f"{username}:{path}".encode('utf-8')
    return hmac.new(SECRET_KEY, msg, hashlib.sha256).hexdigest()

def verify_token(username, path, token):
    expected = generate_token(username, path)
    return hmac.compare_digest(expected, token)

def normalize_path(user_path):
    """Normalize unicode in path to prevent homoglyph attacks"""
    normalized = unicodedata.normalize('NFKC', user_path)
    return normalized

def is_safe_path(base, user_path):
    """Validate that the resolved path is within the base directory.
    Uses os.path.realpath for definitive resolution."""
    # Normalize unicode characters using NFKC (compatibility decomposition)
    clean_path = normalize_path(user_path)

    # Reject obvious traversal attempts
    if '..' in clean_path:
        return False, None

    # Reject null bytes
    if '\x00' in clean_path:
        return False, None

    # Construct the full path
    full_path = os.path.join(BASE_DIR, clean_path)

    # Resolve the REAL path (follows symlinks, resolves all components)
    resolved = os.path.realpath(full_path)

    # Ensure it starts with the real base directory
    real_base = os.path.realpath(BASE_DIR)
    if not resolved.startswith(real_base + os.sep) and resolved != real_base:
        return False, None

    # Check extension
    ext = os.path.splitext(resolved)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return False, None

    return True, resolved

def sanitize_filename(filename):
    """Remove potentially dangerous characters from filename.
    Only allow ASCII alphanumeric, dots, hyphens, underscores, forward slashes."""
    sanitized = ''
    for ch in filename:
        if ch.isascii() and (ch.isalnum() or ch in './-_'):
            sanitized += ch
        else:
            sanitized += '_'
    return sanitized

@app.route('/api/documents/<path:filepath>', methods=['GET'])
def get_document(filepath):
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401

    parts = auth_header[7:].split(':')
    if len(parts) != 2:
        return jsonify({'error': 'Invalid token format'}), 401

    username, token = parts[0], parts[1]

    # Sanitize the filepath - ASCII only
    clean_filepath = sanitize_filename(filepath)

    # Verify the access token
    if not verify_token(username, clean_filepath, token):
        return jsonify({'error': 'Access denied'}), 403

    # Validate path safety
    safe, resolved_path = is_safe_path(BASE_DIR, clean_filepath)
    if not safe:
        return jsonify({'error': 'Invalid path'}), 400

    if not os.path.isfile(resolved_path):
        return jsonify({'error': 'Not found'}), 404

    return send_file(resolved_path)

@app.route('/api/documents', methods=['POST'])
def upload_document():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401

    parts = auth_header[7:].split(':')
    if len(parts) != 2:
        return jsonify({'error': 'Invalid token format'}), 401

    username, token = parts[0], parts[1]

    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    dest_path = request.form.get('path', '')

    if not dest_path:
        return jsonify({'error': 'No destination path'}), 400

    # Sanitize destination path - ASCII only
    clean_dest = sanitize_filename(dest_path)

    # Verify upload token
    if not verify_token(username, clean_dest, token):
        return jsonify({'error': 'Access denied'}), 403

    # Validate path safety
    safe, resolved_path = is_safe_path(BASE_DIR, clean_dest)
    if not safe:
        return jsonify({'error': 'Invalid path'}), 400

    # Ensure parent directory exists
    parent_dir = os.path.dirname(resolved_path)
    os.makedirs(parent_dir, exist_ok=True)

    # Save the file
    file.save(resolved_path)

    return jsonify({'status': 'uploaded', 'path': clean_dest}), 201

@app.route('/api/search', methods=['GET'])
def search_documents():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401

    parts = auth_header[7:].split(':')
    if len(parts) != 2:
        return jsonify({'error': 'Invalid token format'}), 401

    username, token = parts[0], parts[1]
    query = request.args.get('q', '')

    # Verify the caller actually owns this username before listing their files.
    # The token is bound to (username, username) as the scope for search access.
    if not verify_token(username, username, token):
        return jsonify({'error': 'Access denied'}), 403

    # Normalize the search query for consistent matching
    normalized_query = unicodedata.normalize('NFKC', query).lower()

    results = []
    user_dir = os.path.join(BASE_DIR, username)
    real_user_dir = os.path.realpath(user_dir)
    real_base = os.path.realpath(BASE_DIR)

    # Verify user directory is within base
    if not real_user_dir.startswith(real_base + os.sep):
        return jsonify({'results': []})

    if os.path.isdir(real_user_dir):
        for root, dirs, files in os.walk(real_user_dir):
            for fname in files:
                normalized_fname = unicodedata.normalize('NFKC', fname).lower()
                if normalized_query in normalized_fname:
                    full = os.path.realpath(os.path.join(root, fname))
                    if full.startswith(real_base + os.sep):
                        rel_path = os.path.relpath(full, BASE_DIR)
                        results.append(rel_path)

    return jsonify({'results': results[:50]})

if __name__ == '__main__':
    os.makedirs(BASE_DIR, exist_ok=True)
    app.run(host='127.0.0.1', port=8080)
